import java.io.*;
import java.util.*;

public class VanyaAndScaleVariant5 {
    static long[] a;
    static boolean result;
    static int totalCount;
    static long leftSum, rightSum;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long limit = (long) 1e11;
        a = new long[40];
        int index = 1;
        long powerVal = 1;
        a[0] = 1;
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        for (int i = 1; i < 16; i++) {
            a[index] = powerVal * w;
            powerVal *= w;
            if (powerVal > limit) break;
            index++;
        }
        leftSum = 0;
        rightSum = m;
        totalCount = index;
        result = false;
        searchAll(0);
        System.out.println(result ? "YES" : "NO");
    }

    static void searchAll(int pos) {
        if (pos == totalCount) {
            if (leftSum == rightSum) {
                result = true;
            }
            return;
        }
        if (result) return;
        for (int choice = 0; choice < 3; choice++) {
            if (result) return;
            if (choice == 1) {
                leftSum += a[pos];
                searchAll(pos + 1);
                leftSum -= a[pos];
            } else if (choice == 2) {
                rightSum += a[pos];
                searchAll(pos + 1);
                rightSum -= a[pos];
            } else {
                searchAll(pos + 1);
            }
        }
    }
}
